'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'

const formSchema = z.object({
  name: z.string().min(1, 'Name is required').max(100),
  designation: z.string().max(100).optional(),
  email: z.string().email('Invalid email address'),
  hook: z.string().min(2, 'Hook must be at least 2 characters').max(500, 'Hook must be 500 characters or less'),
})

type FormData = z.infer<typeof formSchema>

interface HookGraderFormProps {
  onSubmit: (data: FormData) => Promise<void>
  isLoading: boolean
  error?: string
}

export function HookGraderForm({ onSubmit, isLoading, error }: HookGraderFormProps) {
  const [submitError, setSubmitError] = useState<string | undefined>(error)

  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm<FormData>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      name: '',
      designation: '',
      email: '',
      hook: '',
    },
  })

  const handleFormSubmit = async (data: FormData) => {
    setSubmitError(undefined)
    try {
      await onSubmit(data)
    } catch (err) {
      setSubmitError(err instanceof Error ? err.message : 'Something went wrong')
    }
  }

  return (
    <form onSubmit={handleSubmit(handleFormSubmit)} className="space-y-6" noValidate>
      {submitError && (
        <div className="p-4 bg-red-50 border border-red-200 text-red-700 rounded-lg animate-fade-in" role="alert">
          {submitError}
        </div>
      )}

      <div className="space-y-4">
        <div>
          <label htmlFor="name" className="block text-sm font-medium text-myntmore-primary dark:text-myntmore-light mb-1">
            Full Name <span className="text-red-500">*</span>
          </label>
          <input
            {...register('name')}
            id="name"
            type="text"
            placeholder="John Doe"
            className={`w-full px-4 py-3 rounded-lg border ${
              errors.name
                ? 'border-red-300 focus:border-red-500 focus:ring-red-500'
                : 'border-gray-300 focus:border-myntmore-gold focus:ring-myntmore-gold'
            } bg-white dark:bg-myntmore-secondary text-myntmore-primary dark:text-myntmore-light focus:ring-2 focus:ring-offset-0 transition-colors`}
            disabled={isLoading}
            aria-invalid={errors.name ? 'true' : 'false'}
            aria-describedby={errors.name ? 'name-error' : undefined}
          />
          {errors.name && (
            <p id="name-error" className="mt-1 text-sm text-red-500" role="alert">{errors.name.message}</p>
          )}
        </div>

        <div>
          <label htmlFor="designation" className="block text-sm font-medium text-myntmore-primary dark:text-myntmore-light mb-1">
            Designation (Optional)
          </label>
          <input
            {...register('designation')}
            id="designation"
            type="text"
            placeholder="Founder & CEO"
            className={`w-full px-4 py-3 rounded-lg border ${
              errors.designation
                ? 'border-red-300 focus:border-red-500 focus:ring-red-500'
                : 'border-gray-300 focus:border-myntmore-gold focus:ring-myntmore-gold'
            } bg-white dark:bg-myntmore-secondary text-myntmore-primary dark:text-myntmore-light focus:ring-2 focus:ring-offset-0 transition-colors`}
            disabled={isLoading}
          />
          {errors.designation && (
            <p className="mt-1 text-sm text-red-500" role="alert">{errors.designation.message}</p>
          )}
        </div>

        <div>
          <label htmlFor="email" className="block text-sm font-medium text-myntmore-primary dark:text-myntmore-light mb-1">
            Email <span className="text-red-500">*</span>
          </label>
          <input
            {...register('email')}
            id="email"
            type="email"
            placeholder="john@example.com"
            className={`w-full px-4 py-3 rounded-lg border ${
              errors.email
                ? 'border-red-300 focus:border-red-500 focus:ring-red-500'
                : 'border-gray-300 focus:border-myntmore-gold focus:ring-myntmore-gold'
            } bg-white dark:bg-myntmore-secondary text-myntmore-primary dark:text-myntmore-light focus:ring-2 focus:ring-offset-0 transition-colors`}
            disabled={isLoading}
            aria-invalid={errors.email ? 'true' : 'false'}
            aria-describedby={errors.email ? 'email-error' : undefined}
          />
          {errors.email && (
            <p id="email-error" className="mt-1 text-sm text-red-500" role="alert">{errors.email.message}</p>
          )}
        </div>
      </div>

      <div>
        <label htmlFor="hook" className="block text-sm font-medium text-myntmore-primary dark:text-myntmore-light mb-1">
          LinkedIn Hook (First Two Lines) <span className="text-red-500">*</span>
        </label>
        <textarea
          {...register('hook')}
          id="hook"
          rows={4}
          placeholder="Paste the first two lines of your LinkedIn post here..."
          className={`w-full px-4 py-3 rounded-lg border ${
            errors.hook
              ? 'border-red-300 focus:border-red-500 focus:ring-red-500'
              : 'border-gray-300 focus:border-myntmore-gold focus:ring-myntmore-gold'
            } bg-white dark:bg-myntmore-secondary text-myntmore-primary dark:text-myntmore-light focus:ring-2 focus:ring-offset-0 transition-colors resize-y min-h-[100px]`}
          disabled={isLoading}
          aria-invalid={errors.hook ? 'true' : 'false'}
          aria-describedby={errors.hook ? 'hook-error' : 'hook-hint'}
        />
        {errors.hook && (
          <p id="hook-error" className="mt-1 text-sm text-red-500" role="alert">{errors.hook.message}</p>
        )}
        <p id="hook-hint" className="mt-1 text-sm text-gray-500 dark:text-gray-400">
          Paste the first two lines of your LinkedIn post. We'll score it out of 100 and give you 3 rewrites.
        </p>
      </div>

      <button
        type="submit"
        disabled={isLoading}
        className="w-full py-3 px-6 bg-myntmore-primary dark:bg-myntmore-gold text-white dark:text-myntmore-primary font-medium rounded-lg hover:bg-myntmore-accent dark:hover:bg-yellow-500 focus:ring-2 focus:ring-myntmore-gold focus:ring-offset-2 dark:focus:ring-offset-myntmore-primary disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
      >
        {isLoading ? (
          <span className="flex items-center justify-center gap-2">
            <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" />
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
            </svg>
            Grading...
          </span>
        ) : (
          'Grade My Hook'
        )}
      </button>
    </form>
  )
}

'use client'

import { useState } from 'react'

interface RewriteCardProps {
  index: number
  hook: string
  reason: string
  onCopy: (text: string) => void
  isFallback: boolean
}

export function RewriteCard({ index, hook, reason, onCopy, isFallback }: RewriteCardProps) {
  const [copied, setCopied] = useState(false)

  const handleCopy = () => {
    navigator.clipboard.writeText(hook)
    onCopy(hook)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <div className={`bg-white dark:bg-myntmore-secondary rounded-xl p-5 border ${
      isFallback ? 'border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-900/20' : 'border-gray-200 dark:border-gray-700'
    }`}>
      <div className="flex items-start justify-between gap-4 mb-3">
        <span className={`font-bold text-lg ${isFallback ? 'text-amber-700 dark:text-amber-300' : 'text-myntmore-primary dark:text-myntmore-light'}`}>
          Rewrite {index}
        </span>
        {isFallback && (
          <span className="px-2 py-0.5 text-xs font-medium bg-amber-100 text-amber-700 dark:bg-amber-900 dark:text-amber-300 rounded-full">
            Fallback
          </span>
        )}
      </div>

      <div className="mb-3">
        <p className="text-myntmore-primary dark:text-myntmore-light font-medium leading-relaxed">"{hook}"</p>
      </div>

      <div className="flex items-center justify-between pt-3 border-t border-gray-200 dark:border-gray-700">
        <p className="text-sm text-gray-600 dark:text-gray-400">
          <span className="font-medium text-gray-900 dark:text-gray-100">Why:</span> {reason}
        </p>
        <button
          onClick={handleCopy}
          className={`px-3 py-1.5 text-sm font-medium rounded-lg transition-colors ${
            copied
              ? 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300'
              : 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'
          }`}
          aria-label={copied ? 'Copied to clipboard' : 'Copy to clipboard'}
        >
          {copied ? (
            <>
              <svg className="inline w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
              Copied!
            </>
          ) : (
            <>
              <svg className="inline w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 012-2h10a2 2 0 012 2v1M8 5a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1" />
              </svg>
              Copy
            </>
          )}
        </button>
      </div>
    </div>
  )
}

/**
 * API Route: POST /api/grade-hook
 * Grades a LinkedIn hook, generates rewrites, persists session atomically
 */

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { scoreHook } from '@/lib/scoring'
import { generateRewrites, type RewriteResult } from '@/lib/gemini/rewrite'
import { insertSessionAtomic } from '@/lib/supabase/queries'
import { buildWebhookPayload } from '@/lib/webhook/make'
import { randomUUID } from 'crypto'

// Request validation schema
const requestSchema = z.object({
  name: z.string().min(1).max(100),
  designation: z.string().max(100).optional().nullable(),
  email: z.string().email(),
  hook: z.string().min(2).max(500),
})

export async function POST(request: NextRequest) {
  const startTime = Date.now()

  try {
    // Parse and validate request
    const body = await request.json()
    const validation = requestSchema.safeParse(body)

    if (!validation.success) {
      return NextResponse.json(
        {
          error: 'VALIDATION_ERROR',
          message: 'Invalid request body',
          details: validation.error.errors.map(e => ({
            field: e.path.join('.'),
            message: e.message,
          })),
        },
        { status: 400 }
      )
    }

    const { name, designation, email, hook } = validation.data

    // Step 1: Deterministic scoring
    const scoreResult = scoreHook(hook)

    // Step 2: Generate rewrites via Gemini
    const rewriteResult = await generateRewrites(hook, scoreResult.score, scoreResult.failedRules)

    // Step 3: Prepare rewrites for storage
    const rewrites = rewriteResult.rewrites

    // Step 4: Build webhook payload for outbox
    const sessionId = randomUUID()
    const idempotencyKey = `hook_grader_${sessionId}`
    const webhookPayload = buildWebhookPayload(
      sessionId,
      idempotencyKey,
      { name, designation: designation || null, email },
      {
        original: hook,
        score: scoreResult.score,
        failed_rules: scoreResult.failedRules,
        passed_rules: scoreResult.passedRules,
      },
      rewrites,
      {
        ip_hash: request.headers.get('x-forwarded-for')
          ? Buffer.from(request.headers.get('x-forwarded-for') || '').toString('base64').slice(0, 64)
          : null,
        user_agent: request.headers.get('user-agent') || null,
        processing_ms: Date.now() - startTime,
      }
    )

    // Step 5: Atomic insert session + outbox
    await insertSessionAtomic({
      name,
      designation: designation || null,
      email,
      original_hook: hook,
      score: scoreResult.score,
      failed_rules: scoreResult.failedRules,
      passed_rules: scoreResult.passedRules,
      rewrite_1: rewrites[0].hook,
      rewrite_1_reason: rewrites[0].reason,
      rewrite_2: rewrites[1].hook,
      rewrite_2_reason: rewrites[1].reason,
      rewrite_3: rewrites[2].hook,
      rewrite_3_reason: rewrites[2].reason,
      ip_hash: webhookPayload.metadata.ip_hash as string | null,
      user_agent: webhookPayload.metadata.user_agent as string | null,
      processing_ms: webhookPayload.metadata.processing_ms as number,
      idempotency_key: idempotencyKey,
      payload: webhookPayload,
    })

    // Step 6: Return response
    const response = {
      sessionId,
      score: scoreResult.score,
      failedRules: scoreResult.failedRules,
      passedRules: scoreResult.passedRules,
      rewrites: rewrites.map(r => ({ hook: r.hook, reason: r.reason })),
      fallback: rewriteResult.fallback,
      fallbackReason: rewriteResult.fallbackReason,
    }

    return NextResponse.json(response, { status: 200 })
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error'
    console.error('Error grading hook:', errorMessage)

    // Check if it's a persistence error
    if (errorMessage.includes('insert session') || errorMessage.includes('RPC') || errorMessage.includes('database')) {
      return NextResponse.json(
        {
          error: 'PERSISTENCE_FAILED',
          message: 'Failed to save session. Please try again.',
          requestId: randomUUID(),
        },
        { status: 500 }
      )
    }

    // Generic server error
    return NextResponse.json(
      {
        error: 'INTERNAL_ERROR',
        message: 'An unexpected error occurred. Please try again.',
        requestId: randomUUID(),
      },
      { status: 500 }
    )
  }
}

/**
 * Scoring Rules Implementation
 * Each rule is a pure function that returns boolean.
 * No external dependencies, no AI, fully deterministic.
 */

import { SCORING_CONSTANTS } from './constants'
import { Rule } from './types'

/**
 * R1: Length Rule
 * Optimal range: 80-160 characters for two lines
 */
export function lengthRule(hook: string): boolean {
  const trimmed = hook.trim()
  return trimmed.length >= SCORING_CONSTANTS.length.min && trimmed.length <= SCORING_CONSTANTS.length.max
}

/**
 * R2: Curiosity Gap Rule
 * Contains ? OR curiosity-triggering words
 */
export function curiosityRule(hook: string): boolean {
  const lower = hook.toLowerCase()

  // Check for question mark
  if (SCORING_CONSTANTS.curiosity.questionMark && hook.includes('?')) {
    return true
  }

  // Check for curiosity words
  return SCORING_CONSTANTS.curiosity.words.some(word => lower.includes(word))
}

/**
 * R3: Specificity Rule
 * Contains at least one of: digits, timeframes, proper nouns, currency, percentages
 */
export function specificityRule(hook: string): boolean {
  const constants = SCORING_CONSTANTS.specificity

  // Check for digits
  if (constants.digitPattern.test(hook)) {
    return true
  }

  // Check for timeframe patterns
  if (constants.timeframePatterns.some(pattern => pattern.test(hook))) {
    return true
  }

  // Check for currency symbols
  if (constants.currencyPatterns.some(pattern => pattern.test(hook))) {
    return true
  }

  // Check for percentage
  if (constants.percentagePattern.test(hook)) {
    return true
  }

  // Check for proper nouns: either two+ consecutive capitalized words, OR first word is long enough (>= 7 chars)
  const hasTwoOrMoreConsecutiveCapWords = /[A-Z][a-z]+(?:\s+[A-Z][a-z]+)+/.test(hook);
  const firstWord = hook.split(/\s+/)[0];
  const isFirstWordLongEnough = firstWord && firstWord.length >= 7;
  if (hasTwoOrMoreConsecutiveCapWords || isFirstWordLongEnough) {
    return true;
  }

  return false
}

/**
 * R4: Authority Signal Rule
 * Contains first-person pronoun AND outcome/claim verb
 */
export function authorityRule(hook: string): boolean {
  const constants = SCORING_CONSTANTS.authority

  const hasFirstPerson = constants.firstPersonPronouns.test(hook)
  const hasOutcomeVerb = constants.outcomeVerbs.test(hook)

  return hasFirstPerson && hasOutcomeVerb
}

/**
 * R5: Action Orientation Rule
 * Starts with imperative verb OR contains action-oriented phrases
 */
export function actionRule(hook: string): boolean {
  const constants = SCORING_CONSTANTS.action
  const trimmed = hook.trim()
  const lower = trimmed.toLowerCase()

  // Check if starts with imperative verb
  if (constants.imperativeStart.test(trimmed)) {
    return true
  }

  // Check for action phrases
  return constants.actionPhrases.some(phrase => lower.includes(phrase))
}

/**
 * R6: Clickbait Penalty Rule (negative weight)
 * Returns true if NO clickbait patterns detected (no penalty)
 * Returns false if clickbait patterns detected (penalty applies)
 */
export function clickbaitPenaltyRule(hook: string): boolean {
  const constants = SCORING_CONSTANTS.clickbait
  const lower = hook.toLowerCase()

  // Check for clickbait phrases
  const hasClickbaitPhrase = constants.phrases.some(phrase => lower.includes(phrase))
  if (hasClickbaitPhrase) {
    return false
  }

  // Check for excessive exclamation marks
  const exclamationCount = (hook.match(/!/g) || []).length
  if (exclamationCount >= constants.exclamationThreshold) {
    return false
  }

  // Check for ALL CAPS words longer than threshold (letters only)
  const words = hook.split(/\s+/)
  const hasExcessiveCaps = words.some(word => {
    // Only check words that consist entirely of letters, are all caps, and longer than threshold
    if (word.length > constants.capsThreshold && word === word.toUpperCase() && /^[A-Z]+$/.test(word)) {
      // Exclude common acronyms
      const acronyms = ['ARR', 'ROI', 'CEO', 'CTO', 'CFO', 'VP', 'HR', 'IT', 'AI', 'ML', 'SaaS', 'B2B', 'B2C', 'KPI', 'OKR', 'SEO', 'SEM', 'CRM', 'CMS', 'API', 'SDK', 'UI', 'UX']
      return !acronyms.includes(word)
    }
    return false
  })

  if (hasExcessiveCaps) {
    return false
  }

  return true // Pass = no clickbait detected
}

/**
 * All rules with their metadata
 */
export const ALL_RULES = [
  {
    id: 'R1',
    weight: SCORING_CONSTANTS.weights.length,
    check: lengthRule,
    passReason: 'Optimal length (80-160 chars)',
    failReason: 'Hook length outside optimal range (80-160 chars)',
  },
  {
    id: 'R2',
    weight: SCORING_CONSTANTS.weights.curiosity,
    check: curiosityRule,
    passReason: 'Contains question or curiosity trigger',
    failReason: 'No question or curiosity gap detected',
  },
  {
    id: 'R3',
    weight: SCORING_CONSTANTS.weights.specificity,
    check: specificityRule,
    passReason: 'Contains specific numbers, timeframes, or concrete outcomes',
    failReason: 'Lacks specific numbers, timeframes, or concrete outcomes',
  },
  {
    id: 'R4',
    weight: SCORING_CONSTANTS.weights.authority,
    check: authorityRule,
    passReason: 'First-person authority signal with outcome present',
    failReason: 'Missing first-person authority signal with outcome',
  },
  {
    id: 'R5',
    weight: SCORING_CONSTANTS.weights.action,
    check: actionRule,
    passReason: 'Action-oriented language or imperative structure',
    failReason: 'Not action-oriented; no imperative or reader-focused structure',
  },
  {
    id: 'R6',
    weight: SCORING_CONSTANTS.weights.clickbaitPenalty,
    check: clickbaitPenaltyRule,
    passReason: 'No clickbait patterns detected',
    failReason: 'Clickbait pattern detected',
  },
] as const

export type RuleDefinition = typeof ALL_RULES[number]

/**
 * NVIDIA NIM client (OpenAI-compatible chat completions)
 * Server-side only — never expose NVIDIA_API_KEY to the browser
 */

export const NVIDIA_API_URL =
  process.env.NVIDIA_API_URL || 'https://integrate.api.nvidia.com/v1/chat/completions'

/** Live-tested 2026-10-14 against this account's NVIDIA key */
export const NVIDIA_MODEL =
  process.env.NVIDIA_MODEL || 'meta/llama-3.2-11b-vision-instruct'

export type Rewrite = {
  hook: string
  reason: string
}

export type NvidiaResponse = {
  rewrites: Rewrite[]
}

export function getNvidiaApiKey(): string {
  const apiKey = process.env.NVIDIA_API_KEY
  if (!apiKey) {
    throw new Error('NVIDIA_API_KEY environment variable is required')
  }
  return apiKey
}

/**
 * Call NVIDIA chat completions and return assistant text
 */
export async function callNvidiaChat(
  systemPrompt: string,
  userPrompt: string,
  options?: { temperature?: number; maxTokens?: number; timeoutMs?: number }
): Promise<string> {
  const apiKey = getNvidiaApiKey()
  const controller = new AbortController()
  const timeoutMs = options?.timeoutMs ?? 45000
  const timer = setTimeout(() => controller.abort(), timeoutMs)

  try {
    const response = await fetch(NVIDIA_API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: NVIDIA_MODEL,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt },
        ],
        temperature: options?.temperature ?? 0.7,
        max_tokens: options?.maxTokens ?? 2048,
      }),
      signal: controller.signal,
    })

    const json = (await response.json()) as {
      error?: { message?: string }
      choices?: Array<{ message?: { content?: string } }>
    }

    if (!response.ok) {
      throw new Error(json.error?.message || `NVIDIA HTTP ${response.status}`)
    }

    const text = json.choices?.[0]?.message?.content
    if (!text || !text.trim()) {
      throw new Error('Empty response from NVIDIA')
    }
    return text
  } finally {
    clearTimeout(timer)
  }
}

/**
 * Gemini Prompt Templates
 * Follows Task 1 writing rules strictly.
 */

import { Rewrite } from './client'

/**
 * System prompt that enforces writing rules
 */
export const SYSTEM_PROMPT = `You are an expert LinkedIn copywriter for Myntmore, a B2B growth marketing agency. 
Your job is to rewrite the first two lines of LinkedIn posts to make them more engaging.

STRICT WRITING RULES - NEVER VIOLATE:
1. NO JARGON - Use plain, conversational English
2. NO EM DASHES (—) - Use commas, periods, or colons instead
3. NO INVENTED NUMBERS/CLAIMS - Only use facts from the original hook; never fabricate metrics, revenue, customers, or results
4. UNDER 120 WORDS per rewrite
5. ONLY CTA ALLOWED: "myntmore.com/founder-meeting" - no other links or CTAs
6. Keep the person's actual voice and experience - enhance, don't replace

Your output must be valid JSON matching the required schema exactly.`

/**
 * Build user prompt with original hook, score, and context
 */
export function buildUserPrompt(originalHook: string, score: number, failedRules: string[]): string {
  return `Original hook (first two lines of LinkedIn post):
"${originalHook}"

Current score: ${score}/100
Areas to improve: ${failedRules.join('; ') || 'None'}

Generate exactly 3 distinct rewrites that:
1. Fix the weaknesses identified above
2. Keep the author's actual experience/claims intact
3. Follow all writing rules strictly
4. Are meaningfully different from each other (different angles/structures)

Each rewrite needs a "reason" explaining what was changed and why it works better.

Return JSON with exactly 3 rewrites in the "rewrites" array.`
}

/**
 * Parse and validate Gemini response
 */
export function parseGeminiResponse(text: string): Rewrite[] {
  try {
    const parsed = JSON.parse(text)
    const rawList = Array.isArray(parsed)
      ? parsed
      : parsed && typeof parsed === 'object' && Array.isArray((parsed as { rewrites?: unknown }).rewrites)
        ? (parsed as { rewrites: unknown[] }).rewrites
        : null

    if (!rawList) {
      throw new Error('Invalid response structure: missing rewrites array')
    }

    if (rawList.length !== 3) {
      throw new Error(`Expected 3 rewrites, got ${rawList.length}`)
    }

    const rewrites = rawList.map((r: unknown, index: number) => {
      if (!r || typeof r !== 'object') {
        throw new Error(`Rewrite ${index + 1} is not an object`)
      }
      const rewrite = r as Record<string, unknown>
      if (typeof rewrite.hook !== 'string' || typeof rewrite.reason !== 'string') {
        throw new Error(`Rewrite ${index + 1} missing hook or reason`)
      }
      if (rewrite.hook.trim().length === 0) {
        throw new Error(`Rewrite ${index + 1} hook is empty`)
      }
      if (rewrite.reason.trim().length === 0) {
        throw new Error(`Rewrite ${index + 1} reason is empty`)
      }
      return {
        hook: rewrite.hook.trim(),
        reason: rewrite.reason.trim(),
      }
    })

    // Validate word count (< 120 words each)
    for (let i = 0; i < rewrites.length; i++) {
      const wordCount = rewrites[i].hook.split(/\s+/).length
      if (wordCount > 120) {
        throw new Error(`Rewrite ${i + 1} exceeds 120 words (${wordCount})`)
      }
    }

    // Check for em dashes (should not have any)
    for (let i = 0; i < rewrites.length; i++) {
      if (rewrites[i].hook.includes('—')) {
        throw new Error(`Rewrite ${i + 1} contains em dash (—)`)
      }
    }

    return rewrites
  } catch (error) {
    throw new Error(`Failed to parse Gemini response: ${error instanceof Error ? error.message : 'Unknown error'}`)
  }
}

/**
 * NVIDIA rewrite generation for Hook Grader
 * Score remains deterministic (lib/scoring). NVIDIA only produces rewrites.
 */

import { callNvidiaChat, type Rewrite } from './client'
import { SYSTEM_PROMPT, buildUserPrompt, parseGeminiResponse } from './prompt'

export type { Rewrite }
export type FallbackReason =
  | 'NVIDIA_TIMEOUT'
  | 'NVIDIA_SCHEMA_ERROR'
  | 'NVIDIA_RATE_LIMIT'
  | 'NVIDIA_UNAVAILABLE'
  // Legacy aliases kept for older clients/tests during transition
  | 'GEMINI_TIMEOUT'
  | 'GEMINI_SCHEMA_ERROR'
  | 'GEMINI_RATE_LIMIT'
  | 'GEMINI_UNAVAILABLE'

export interface RewriteResult {
  rewrites: Rewrite[]
  fallback: boolean
  fallbackReason?: FallbackReason
}

function stripCodeFences(text: string): string {
  return text.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim()
}

/**
 * Generate exactly 3 rewrites via NVIDIA; fall back clearly if unavailable
 */
export async function generateRewrites(
  originalHook: string,
  score: number,
  failedRules: string[]
): Promise<RewriteResult> {
  const prompt = buildUserPrompt(originalHook, score, failedRules)

  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      const text = await callNvidiaChat(SYSTEM_PROMPT, prompt, {
        temperature: 0.7,
        maxTokens: 2048,
        timeoutMs: 45000,
      })

      const rewrites = parseGeminiResponse(stripCodeFences(text))

      return {
        rewrites,
        fallback: false,
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error'
      const isAbort = error instanceof Error && error.name === 'AbortError'

      const isSchemaError =
        errorMessage.includes('schema') ||
        errorMessage.includes('JSON') ||
        errorMessage.includes('rewrites') ||
        errorMessage.includes('Invalid response') ||
        errorMessage.includes('em dash') ||
        errorMessage.includes('word count') ||
        errorMessage.includes('120 words')

      const isRateLimit = errorMessage.includes('429') || errorMessage.includes('rate limit')
      const isTimeout =
        isAbort || errorMessage.includes('timeout') || errorMessage.includes('deadline')

      if (isSchemaError && attempt < 2) {
        console.warn(`NVIDIA schema error (attempt ${attempt}), retrying:`, errorMessage)
        continue
      }

      if (isRateLimit || isTimeout) {
        return createFallbackResult(
          originalHook,
          isRateLimit ? 'NVIDIA_RATE_LIMIT' : 'NVIDIA_TIMEOUT'
        )
      }

      if (attempt === 2) {
        console.error('NVIDIA failed after retries:', errorMessage)
        return createFallbackResult(originalHook, 'NVIDIA_UNAVAILABLE')
      }

      console.warn(`NVIDIA error (attempt ${attempt}), retrying:`, errorMessage)
    }
  }

  return createFallbackResult(originalHook, 'NVIDIA_UNAVAILABLE')
}

export function createFallbackResult(originalHook: string, reason: FallbackReason): RewriteResult {
  const fallbackRewrite = {
    hook: originalHook,
    reason: 'AI unavailable — original hook shown',
  }

  return {
    rewrites: [fallbackRewrite, fallbackRewrite, fallbackRewrite],
    fallback: true,
    fallbackReason: reason,
  }
}

export function generateFallbackRewrites(
  originalHook: string,
  reason: FallbackReason = 'NVIDIA_UNAVAILABLE'
): RewriteResult {
  return createFallbackResult(originalHook, reason)
}

/**
 * Supabase Server Client
 * Service-role client for API routes - never exposed to browser
 * Lazy initialization to avoid build-time errors
 */

import { createClient } from '@supabase/supabase-js'

let supabaseInstance: ReturnType<typeof createClient> | null = null

/**
 * Get or create the Supabase client instance (lazy initialization)
 */
export function getSupabase() {
  if (!supabaseInstance) {
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
    // Prefer service role; fall back to publishable/anon when service role is unset
    // (assignment local/dev). Never expose this client to the browser.
    const supabaseKey =
      process.env.SUPABASE_SERVICE_ROLE_KEY ||
      process.env.SUPABASE_PUBLISHABLE_KEY ||
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

    if (!supabaseUrl || !supabaseKey) {
      throw new Error(
        'Missing Supabase environment variables: NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY (or SUPABASE_PUBLISHABLE_KEY)'
      )
    }

    supabaseInstance = createClient(supabaseUrl, supabaseKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    })
  }
  return supabaseInstance
}

// For backward compatibility, export a getter that throws if not initialized
// This should only be used in runtime, not at build time
export const supabase = {
  get: () => {
    const instance = getSupabase()
    if (!instance) {
      throw new Error('Supabase client not initialized. This should not happen at runtime.')
    }
    return instance
  }
} as any

/**
 * Supabase Query Helpers
 * All database operations for Hook Grader
 */

import { supabase } from './server'
import type {
  HookGraderSession,
  WebhookOutbox,
  WebhookDelivery,
  WebhookPayload,
  InsertHookGraderSessionParams,
  InsertHookGraderSessionResult,
} from './types'

/**
 * Insert session and outbox atomically via RPC function
 * This is the primary write operation - single transaction
 */
export async function insertSessionAtomic(params: InsertHookGraderSessionParams): Promise<InsertHookGraderSessionResult> {
  const { data, error } = await supabase.get().rpc('insert_hook_grader_session', {
    p_name: params.name,
    p_designation: params.designation,
    p_email: params.email,
    p_original_hook: params.original_hook,
    p_score: params.score,
    p_failed_rules: params.failed_rules,
    p_passed_rules: params.passed_rules,
    p_rewrite_1: params.rewrite_1,
    p_rewrite_1_reason: params.rewrite_1_reason,
    p_rewrite_2: params.rewrite_2,
    p_rewrite_2_reason: params.rewrite_2_reason,
    p_rewrite_3: params.rewrite_3,
    p_rewrite_3_reason: params.rewrite_3_reason,
    p_ip_hash: params.ip_hash,
    p_user_agent: params.user_agent,
    p_processing_ms: params.processing_ms,
    p_idempotency_key: params.idempotency_key,
    p_payload: params.payload,
  })

  if (error) {
    throw new Error(`Failed to insert session: ${error.message}`)
  }

  if (!data) {
    throw new Error('RPC returned no session ID')
  }

  return { id: data }
}

/**
 * Get session by ID
 */
export async function getSession(sessionId: string): Promise<HookGraderSession | null> {
  const { data, error } = await supabase.get()
    .from('hook_grader_sessions')
    .select('*')
    .eq('id', sessionId)
    .single()

  if (error) {
    if (error.code === 'PGRST116') {
      return null // Not found
    }
    throw new Error(`Failed to get session: ${error.message}`)
  }

  return data
}

/**
 * Get pending webhook outbox entries for processing
 */
export async function getPendingWebhooks(): Promise<WebhookOutbox[]> {
  const { data, error } = await supabase.get()
    .from('webhook_outbox')
    .select('*')
    .eq('status', 'pending')
    .lte('next_retry_at', new Date().toISOString())
    .lt('attempt', 5) // max_attempts is 5
    .order('created_at', { ascending: true })

  if (error) {
    throw new Error(`Failed to get pending webhooks: ${error.message}`)
  }

  return data || []
}

/**
 * Mark webhook as delivered
 */
export async function markWebhookDelivered(outboxId: string, statusCode: number, responseBody: string): Promise<void> {
  const { error } = await supabase.get()
    .from('webhook_outbox')
    .update({
      status: 'delivered',
      delivered_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq('id', outboxId)

  if (error) {
    throw new Error(`Failed to mark webhook delivered: ${error.message}`)
  }

  // Log delivery attempt
  await logWebhookAttempt({
    outbox_id: outboxId,
    attempt: 1, // This will be the final successful attempt
    status_code: statusCode,
    success: true,
    error: null,
    response_body: responseBody,
  })
}

/**
 * Mark webhook as failed and schedule retry
 */
export async function markWebhookFailed(outboxId: string, attempt: number, statusCode: number | null, errorMessage: string, responseBody: string | null): Promise<void> {
  const isLastAttempt = attempt >= 5 // max_attempts

  const { error } = await supabase.get()
    .from('webhook_outbox')
    .update({
      status: isLastAttempt ? 'dead_letter' : 'pending',
      attempt,
      last_error: errorMessage,
      next_retry_at: isLastAttempt ? null : calculateNextRetryAt(attempt),
      updated_at: new Date().toISOString(),
    })
    .eq('id', outboxId)

  if (error) {
    throw new Error(`Failed to mark webhook failed: ${error.message}`)
  }

  // Log delivery attempt
  await logWebhookAttempt({
    outbox_id: outboxId,
    attempt,
    status_code: statusCode,
    success: false,
    error: errorMessage,
    response_body: responseBody,
  })
}

/**
 * Log webhook delivery attempt
 */
export async function logWebhookAttempt(params: {
  outbox_id: string
  attempt: number
  status_code: number | null
  success: boolean
  error: string | null
  response_body: string | null
}): Promise<void> {
  const { error } = await supabase.get().from('webhook_deliveries').insert(params)

  if (error) {
    // Log but don't throw - delivery logging shouldn't break the main flow
    console.error('Failed to log webhook attempt:', error.message)
  }
}

/**
 * Calculate next retry time based on attempt number
 * Minute-aligned schedule: 1m, 5m, 15m, 30m, 60m
 */
function calculateNextRetryAt(attempt: number): string {
  const now = new Date()
  const minutes = [1, 5, 15, 30, 60]
  const delayMinutes = minutes[Math.min(attempt, minutes.length - 1)]
  now.setMinutes(now.getMinutes() + delayMinutes)
  return now.toISOString()
}

/**
 * Get session with webhook delivery status
 */
export async function getSessionWithDeliveryStatus(sessionId: string): Promise<{
  session: HookGraderSession | null
  outbox: WebhookOutbox | null
  deliveries: WebhookDelivery[]
} | null> {
  const session = await getSession(sessionId)
  if (!session) return null

  const { data: outbox, error: outboxError } = await supabase.get()
    .from('webhook_outbox')
    .select('*')
    .eq('session_id', sessionId)
    .single()

  if (outboxError && outboxError.code !== 'PGRST116') {
    throw new Error(`Failed to get outbox: ${outboxError.message}`)
  }

  const { data: deliveries, error: deliveriesError } = await supabase.get()
    .from('webhook_deliveries')
    .select('*')
    .eq('outbox_id', outbox?.id)
    .order('created_at', { ascending: true })

  if (deliveriesError) {
    throw new Error(`Failed to get deliveries: ${deliveriesError.message}`)
  }

  return {
    session,
    outbox: outbox || null,
    deliveries: deliveries || [],
  }
}

/**
 * Make.com Webhook Delivery Client
 * Called by Vercel Cron, not inline in API response
 * Lazy initialization to avoid build-time errors
 */

import type { WebhookOutbox } from '@/lib/supabase/types'

export type { WebhookPayload, WebhookPayloadMetadata } from '@/lib/supabase/types'

const WEBHOOK_TIMEOUT_MS = 10000 // 10 seconds

/**
 * Get the Make.com webhook URL, throwing if not configured.
 * Read from env on each call so tests can stub/clear secrets reliably.
 */
function getMakeWebhookUrl(): string {
  const url = process.env.MAKE_WEBHOOK_URL
  if (!url) {
    throw new Error('MAKE_WEBHOOK_URL environment variable is required')
  }
  return url
}

/**
 * Get the Make.com webhook secret (optional).
 * Empty string is treated as unset (no HMAC header).
 */
function getMakeWebhookSecret(): string | undefined {
  const secret = process.env.MAKE_WEBHOOK_SECRET
  return secret && secret.length > 0 ? secret : undefined
}

/**
 * Generate HMAC signature for webhook verification
 */
async function generateSignature(payload: string, secret: string): Promise<string> {
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey(
    'raw',
    encoder.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  )
  const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(payload))
  return 'sha256=' + Array.from(new Uint8Array(signature))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('')
}

/**
 * Deliver webhook to Make.com
 */
export async function deliverWebhook(outbox: WebhookOutbox): Promise<{ success: boolean; statusCode: number; error?: string; responseBody?: string }> {
  if (!getMakeWebhookUrl()) {
    throw new Error('MAKE_WEBHOOK_URL environment variable is required')
  }

  const payload = outbox.payload
  const payloadString = JSON.stringify(payload)

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'X-Myntmore-Timestamp': Math.floor(Date.now() / 1000).toString(),
    'X-Myntmore-Idempotency-Key': outbox.idempotency_key,
  }

  // Add HMAC signature if secret is configured
  const secret = getMakeWebhookSecret()
  if (secret) {
    headers['X-Myntmore-Signature'] = await generateSignature(payloadString, secret)
  }

  const controller = new AbortController()
  const timeoutId = setTimeout(() => controller.abort(), WEBHOOK_TIMEOUT_MS)

  try {
    const response = await fetch(getMakeWebhookUrl()!, {
      method: 'POST',
      headers,
      body: payloadString,
      signal: controller.signal,
    })

    clearTimeout(timeoutId)

    const responseBody = await response.text().catch(() => '')

    if (!response.ok) {
      return {
        success: false,
        statusCode: response.status,
        error: `HTTP ${response.status}: ${responseBody || response.statusText}`,
        responseBody,
      }
    }

    return {
      success: true,
      statusCode: response.status,
      responseBody,
    }
  } catch (error) {
    clearTimeout(timeoutId)

    if (error instanceof DOMException && error.name === 'AbortError') {
      return {
        success: false,
        statusCode: 0,
        error: 'Webhook timeout (10s)',
      }
    }

    return {
      success: false,
      statusCode: 0,
      error: error instanceof Error ? error.message : 'Unknown error',
    }
  }
}

/**
